def safe_div(a, b):
    try:
        return str(a / b)
    except ZeroDivisionError:
        return "ERROR: zero"

print(safe_div(10, 2), safe_div(10, 0))

def check_int(s):
    try:
        return f"OK:{int(s) * 2}"
    except ValueError:
        return "NG"

print(check_int("7"), check_int("abc"))

import re, json

reply = '<tool_call>{"name": "a"}</tool_call> <tool_call>{bad json</tool_call>'
calls = []
for b in re.findall(r"<tool_call>(.*?)</tool_call>", reply, re.S):
    try:
        calls.append(json.loads(b))
    except json.JSONDecodeError:
        pass
print(len(calls), calls[0]["name"])

