def safe_dispatch(tool_map, name, args):
    if name not in tool_map:
        return "ERROR: unknown tool"
    if not isinstance(args, dict):
        return "ERROR: invalid args"
    try:
        return str(tool_map[name](**args))
    except Exception as e:
        return f"ERROR: {e}"
